#include <iostream>
#include <vector>
#include <stack>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    while (t--) {
        int n, m, a, b;
        cin >> n >> m >> a >> b;
        --a;
        --b;

        vector<vector<int>> graph(n);
        for (int i = 0; i < m; ++i) {
            int x, y;
            cin >> x >> y;
            --x;
            --y;
            graph[x].push_back(y);
            graph[y].push_back(x);
        }

        auto traverse = [&](int start, int blocked) {
            vector<char> visited(n, false);
            stack<int> st;
            visited[blocked] = true;
            visited[start] = true;
            st.push(start);

            while (!st.empty()) {
                int v = st.top();
                st.pop();

                for (int to : graph[v]) {
                    if (!visited[to]) {
                        visited[to] = true;
                        st.push(to);
                    }
                }
            }

            return visited;
        };

        vector<char> fromA = traverse(a, b);
        vector<char> fromB = traverse(b, a);

        long long onlyA = 0;
        long long onlyB = 0;

        for (int v = 0; v < n; ++v) {
            if (v == a || v == b)
                continue;

            if (fromA[v] && !fromB[v])
                ++onlyA;
            if (fromB[v] && !fromA[v])
                ++onlyB;
        }

        cout << onlyA * onlyB << '\n';
    }

    return 0;
}

